INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20VVR82', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A school district conducted a study in which 14 schools were randomly selected. In 7 of these schools, teachers implemented a new reading curriculum (treatment group), while the other 7 schools continued with the existing curriculum (control group). At the end of the year, students in the treatment group scored an average of 11 points higher on a standardized reading test. However, the treatment schools also had, on average, smaller class sizes than the control schools. A district official concludes that the new curriculum caused the improvement in reading scores. Which of the following is the most significant limitation of this conclusion?', NULL, $lyceon_json$[{"key":"A","text":"The study did not use random assignment of individual students to groups."},{"key":"B","text":"The difference in class sizes between the groups is a confounding variable that makes it difficult to attribute the improvement solely to the curriculum."},{"key":"C","text":"The sample of 14 schools is too large for a controlled experiment."},{"key":"D","text":"Standardized test scores are not a valid measure of reading ability."}]$lyceon_json$::jsonb, 'B', NULL, E'Although schools were randomly assigned to groups, the treatment and control groups differed systematically in class size. This difference is a confounding variable: the observed improvement in reading scores could be due to the new curriculum, the smaller class sizes, or a combination of both. Therefore, the causal claim about the curriculum alone is weakened. The distractor about not using random assignment of individual students identifies a real feature of the design (cluster randomization rather than individual randomization), but the more significant limitation stated in the problem is the imbalance in class sizes, which directly confounds the treatment comparison — making this distractor partial reasoning that misses the key issue. The distractor that 14 schools is too large reverses the typical concern (small samples, not large ones, limit statistical power). The distractor about standardized tests not being valid introduces an unsupported claim that is unrelated to the study design limitation described.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21EOSQV', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A biologist records the length, $x$ (in centimeters), and weight, $y$ (in grams), of $30$ fish in a lake. The line of best fit is $y = 3.7x - 18.5$. One fish has a length of $14$ cm and an actual weight of $39$ grams. What is the residual for this fish?', NULL, $lyceon_json$[{"key":"A","text":"$-5.7$"},{"key":"B","text":"$5.7$"},{"key":"C","text":"$33.3$"},{"key":"D","text":"$72.3$"}]$lyceon_json$::jsonb, 'B', NULL, E'The predicted weight is $y = 3.7(14) - 18.5 = 51.8 - 18.5 = 33.3$ grams. The residual is actual minus predicted: $39 - 33.3 = 5.7$. The distractor $-5.7$ reverses the subtraction order (predicted minus actual). The distractor $33.3$ gives the predicted value itself rather than the residual. The distractor $72.3$ adds the actual and predicted values ($39 + 33.3 = 72.3$) instead of subtracting.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM229UGWL', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A cone is inscribed in a cylinder such that they share the same circular base and the same height. The volume of the cylinder is $294\\pi$ cubic units and its height is $6$ units. What is the volume, in cubic units, of the cone?', NULL, $lyceon_json$[{"key":"A","text":"$49\\pi$"},{"key":"B","text":"$98\\pi$"},{"key":"C","text":"$147\\pi$"},{"key":"D","text":"$196\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'From the cylinder volume $\\pi r^2 h = 294\\pi$, substituting $h = 6$ gives $6r^2 = 294$, so $r^2 = 49$. The cone shares the same base and height, so its volume is $\\frac{1}{3}\\pi r^2 h = \\frac{1}{3}\\pi(49)(6) = \\frac{294\\pi}{3} = 98\\pi$. The value $49\\pi$ results from dividing the cylinder volume by the height ($\\frac{294\\pi}{6} = 49\\pi$) without applying the cone volume formula, effectively computing just $r^2\\pi$. The value $147\\pi$ results from dividing the cylinder volume by $2$ instead of $3$, using the wrong fraction for the cone-to-cylinder relationship. The value $196\\pi$ results from a computational error such as evaluating $\\frac{2}{3} \\times 294\\pi = 196\\pi$ instead of $\\frac{1}{3} \\times 294\\pi$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM244HL61', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'The population of a town was $12{,}500$ in 2020. The population increased by $8\\%$ in 2021 and then decreased by $5\\%$ in 2022. What was the population of the town at the end of 2022?', NULL, $lyceon_json$[{"key":"A","text":"$12{,}825$"},{"key":"B","text":"$12{,}875$"},{"key":"C","text":"$13{,}500$"},{"key":"D","text":"$14{,}175$"}]$lyceon_json$::jsonb, 'A', NULL, E'After a $8\\%$ increase in 2021, the population is $12{,}500 \\times 1.08 = 13{,}500$. After a $5\\%$ decrease in 2022, the population is $13{,}500 \\times 0.95 = 12{,}825$. The distractor $12{,}875$ applies a net $3\\%$ increase to the original ($12{,}500 \\times 1.03 = 12{,}875$), incorrectly netting the percentages. The distractor $13{,}500$ computes only the 2021 population and omits the 2022 decrease. The distractor $14{,}175$ applies an $8\\%$ increase followed by a $5\\%$ increase instead of a decrease ($13{,}500 \\times 1.05 = 14{,}175$).', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM259XIMT', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'A bookstore sells hardcover books for $\\$17$ each and paperback books for $\\$9$ each. On a particular day, the store sold $40$ books for a total of $\\$504$. How many hardcover books were sold?', NULL, $lyceon_json$[{"key":"A","text":"$13$"},{"key":"B","text":"$18$"},{"key":"C","text":"$22$"},{"key":"D","text":"$27$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $h$ be the number of hardcover books and $p$ be the number of paperback books. The system is $h + p = 40$ and $17h + 9p = 504$. Substituting $p = 40 - h$: $17h + 9(40 - h) = 504$, so $17h + 360 - 9h = 504$, giving $8h = 144$ and $h = 18$. Then $p = 40 - 18 = 22$. The value $13$ results from an arithmetic slip when subtracting $360$ from $504$: computing $504 - 360 = 104$ instead of $144$, then $104 \\div 8 = 13$. The value $22$ results from solving correctly but reporting the number of paperback books ($40 - 18 = 22$) instead of hardcover books. The value $27$ results from a concept gap: dividing total revenue by the number of books ($504 \\div 40 \\approx 12.6$), rounding to $13$, and then subtracting from the total book count ($40 - 13 = 27$), confusing an average price with a count of books.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26L0YGB', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'A line passes through the points $(1, 13)$ and $(4, 31)$. What is the $y$-intercept of this line?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'First find the slope: $m = \\frac{31 - 13}{4 - 1} = \\frac{18}{3} = 6$. Use point-slope form with the point $(1, 13)$: $y - 13 = 6(x - 1)$. Expand: $y = 6x - 6 + 13 = 6x + 7$. The $y$-intercept is $7$. A common error is computing the slope as $\\frac{31 - 13}{4 + 1} = \\frac{18}{5}$ by adding the $x$-coordinates instead of subtracting (arithmetic slip). Another error is finding the slope correctly but then computing $b = 13 - 6(4) = 13 - 24 = -11$, confusing which point was substituted and making a sign error.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27GQ8A8', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $5x + 4y = 60$?', NULL, $lyceon_json$[{"key":"A","text":"$(0, 12)$"},{"key":"B","text":"$(0, 15)$"},{"key":"C","text":"$(12, 0)$"},{"key":"D","text":"$(15, 0)$"}]$lyceon_json$::jsonb, 'B', NULL, E'To find the $y$-intercept, set $x = 0$: $5(0) + 4y = 60$, so $4y = 60$ and $y = 15$. The $y$-intercept is $(0, 15)$. The point $(0, 12)$ results from dividing $60$ by $5$ instead of $4$, confusing which coefficient applies to $y$. The point $(12, 0)$ is the $x$-intercept found by setting $y = 0$ and dividing $60$ by $5$, confusing $y$-intercept with $x$-intercept. The point $(15, 0)$ uses the correct value $15$ but places it in the $x$-coordinate, confusing $x$-intercept and $y$-intercept.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM288ATC0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'grid_in', E'A store marks up a product by $35\\%$ over its wholesale cost. If the retail price of the product is $\\$94.50$, what is the wholesale cost, in dollars?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '70', ARRAY['70'], E'Let $w$ be the wholesale cost. The retail price is $1.35w = 94.50$, so $w = \\frac{94.50}{1.35} = 70$. The wholesale cost is $\\$70$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28XJDWO', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'mcq', E'A printing shop has $3$ printers that together print $204$ brochures in $4$ hours. The shop then adds $4$ more printers of the same model. At the combined rate of all $7$ printers, how many brochures will be printed in $6$ hours?', NULL, $lyceon_json$[{"key":"A","text":"$306$"},{"key":"B","text":"$476$"},{"key":"C","text":"$714$"},{"key":"D","text":"$1{,}428$"}]$lyceon_json$::jsonb, 'C', NULL, E'First find the rate per printer: $\\frac{204}{3 \\times 4} = \\frac{204}{12} = 17$ brochures per printer per hour. With $7$ printers running for $6$ hours, the total is $17 \\times 7 \\times 6 = 714$. The distractor $306$ uses the original $3$-printer rate ($\\frac{204}{4} = 51$ per hour) and multiplies by $6$ without adjusting for the additional printers. The distractor $476$ divides $204$ by $3$ to get $68$ and multiplies by $7$, neglecting the time dimension. The distractor $1{,}428$ multiplies the original total $204$ by $7$, ignoring the time change entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AAIIDS', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following is equivalent to $4(x^2 + 5x - 2) + 3(2x^2 - x + 6)$?', NULL, $lyceon_json$[{"key":"A","text":"$10x^2 + 17x + 10$"},{"key":"B","text":"$10x^2 + 23x + 10$"},{"key":"C","text":"$10x^2 + 17x - 10$"},{"key":"D","text":"$10x^2 + 23x - 10$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distribute the $4$: $4x^2 + 20x - 8$. Distribute the $3$: $6x^2 - 3x + 18$. Combine like terms: $4x^2 + 6x^2 = 10x^2$, $20x + (-3x) = 17x$, and $-8 + 18 = 10$. The result is $10x^2 + 17x + 10$. The distractor $10x^2 + 23x + 10$ arises from adding the $x$-coefficients $20x + 3x = 23x$ instead of $20x - 3x = 17x$, a sign error on the $-x$ term. The distractor $10x^2 + 17x - 10$ correctly combines the $x$ terms but computes $-8 - 18 = -10$ instead of $-8 + 18 = 10$, an error in combining the constants. The distractor $10x^2 + 23x - 10$ combines both errors: adding $x$-coefficients incorrectly and subtracting constants incorrectly.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AJN662', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A data set contains $11$ values with a mean of $56$. When a $12$th value is added to the set, the new mean becomes $59$. What is the $12$th value?', NULL, $lyceon_json$[{"key":"A","text":"$59$"},{"key":"B","text":"$62$"},{"key":"C","text":"$89$"},{"key":"D","text":"$92$"}]$lyceon_json$::jsonb, 'D', NULL, E'The sum of the original $11$ values is $11 \\times 56 = 616$. The sum of all $12$ values is $12 \\times 59 = 708$. The $12$th value is $708 - 616 = 92$. The distractor $59$ assumes the new value equals the new mean. The distractor $62$ adds the change in mean ($3$) to the new mean ($59 + 3 = 62$). The distractor $89$ uses $10$ instead of $11$ for the original count: $10 \\times 56 = 560$, then $11 \\times 59 - 560 = 649 - 560 = 89$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C0BOQB', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $f$ is defined by $f(x) = (x + 4)^2 - 11$. What is the minimum value of $f(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$-11$"},{"key":"B","text":"$-4$"},{"key":"C","text":"$4$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'A', NULL, E'The function is in vertex form $f(x) = (x + 4)^2 - 11$, where the vertex is at $(-4, -11)$. Since the coefficient of the squared term is positive, the parabola opens upward and the vertex represents the minimum. The minimum value of $f(x)$ is $-11$. The distractor $-4$ comes from confusing the $x$-coordinate of the vertex with the minimum value of the function. The distractor $4$ results from taking the absolute value of the $x$-coordinate of the vertex, ignoring the negative sign. The distractor $11$ arises from dropping the negative sign on the constant term $-11$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CR7Y03', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'mcq', E'What is the value of $x$ in the solution to the system of equations below?$$7x + 2y = 41$$$$3x - 2y = 9$$', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$5$"},{"key":"C","text":"$6$"},{"key":"D","text":"$8$"}]$lyceon_json$::jsonb, 'B', NULL, E'Adding the two equations eliminates $y$: $(7x + 2y) + (3x - 2y) = 41 + 9$, giving $10x = 50$, so $x = 5$. Back-substituting: $2y = 41 - 35 = 6$, so $y = 3$. The value $3$ results from solving correctly but reporting $y = 3$ instead of the requested $x$. The value $6$ results from an arithmetic slip: computing $41 + 9 = 60$ instead of $50$, yielding $10x = 60$ and $x = 6$. The value $8$ results from an equation setup error: subtracting the second equation from the first gives $4x + 4y = 32$, simplifying to $x + y = 8$, then incorrectly interpreting this as $x = 8$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DETEYK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'Two fair six-sided dice are rolled. What is the probability that the sum of the two dice is at least 9, given that at least one of the dice shows a 5?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{5}{36}$"},{"key":"B","text":"$\\frac{5}{18}$"},{"key":"C","text":"$\\frac{4}{11}$"},{"key":"D","text":"$\\frac{5}{11}$"}]$lyceon_json$::jsonb, 'D', NULL, E'First, identify all outcomes where at least one die shows a 5. These are the 11 outcomes: $(5,1), (5,2), (5,3), (5,4), (5,5), (5,6), (1,5), (2,5), (3,5), (4,5), (6,5)$. Of these, the outcomes where the sum is at least 9 are: $(5,4)$ with sum 9, $(5,5)$ with sum 10, $(5,6)$ with sum 11, $(4,5)$ with sum 9, and $(6,5)$ with sum 11 — a total of 5 outcomes. The conditional probability is $\\frac{5}{11}$. The distractor $\\frac{5}{36}$ results from using 36 (all possible dice outcomes) as the denominator instead of conditioning on the 11 outcomes that include at least one 5 — failing to apply conditional probability. The distractor $\\frac{5}{18}$ results from computing the unconditional probability of the sum being at least 9 (there are 10 such outcomes out of 36 total, giving $\\frac{10}{36} = \\frac{5}{18}$) without conditioning on the given event. The distractor $\\frac{4}{11}$ results from miscounting the favorable outcomes as 4 instead of 5, for example by treating $(5,4)$ and $(4,5)$ as a single outcome or omitting one pair.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DG1OJK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'Researchers wanted to determine whether a new fertilizer increases tomato yield. They randomly assigned 60 tomato plants to two groups: one group received the new fertilizer, and the other received a standard fertilizer. At the end of the growing season, the group receiving the new fertilizer had a significantly higher average yield. Which of the following conclusions is best supported by the study design?', NULL, $lyceon_json$[{"key":"A","text":"The new fertilizer caused the increase in tomato yield."},{"key":"B","text":"The new fertilizer is associated with, but did not necessarily cause, the increase in yield."},{"key":"C","text":"The results can be generalized to all types of crops."},{"key":"D","text":"The standard fertilizer caused a decrease in tomato yield."}]$lyceon_json$::jsonb, 'A', NULL, E'Because the study used random assignment to treatment groups, it is a randomized controlled experiment, which allows causal conclusions. The new fertilizer can be said to have caused the higher yield. The distractor limiting the conclusion to association only applies to observational studies where random assignment is not used, not to experiments — this reflects a failure to recognize the study as an experiment. The distractor about generalizing to all crops goes beyond the scope of the study, which tested only tomato plants. The distractor about the standard fertilizer causing a decrease reverses the comparison and misidentifies the treatment effect.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DQ0XCJ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'grid_in', E'A cylinder has a diameter of $18$ centimeters and a height of $7$ centimeters. The volume of the cylinder can be expressed as $k\\pi$ cubic centimeters. What is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '567', ARRAY['567'], E'The radius of the cylinder is $\\frac{18}{2} = 9$ centimeters. The volume is $V = \\pi r^2 h = \\pi(9)^2(7) = \\pi(81)(7) = 567\\pi$ cubic centimeters. Therefore $k = 567$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EAF3A8', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'Which of the following represents all values of $x$ that satisfy $-3(2x - 7) > 39$?', NULL, $lyceon_json$[{"key":"A","text":"$x > -3$"},{"key":"B","text":"$x < -3$"},{"key":"C","text":"$x > 3$"},{"key":"D","text":"$x < 3$"}]$lyceon_json$::jsonb, 'B', NULL, E'Distribute: $-3(2x - 7) = -6x + 21$. The inequality becomes $-6x + 21 > 39$. Subtract $21$: $-6x > 18$. Divide by $-6$ and flip the inequality sign: $x < -3$. The result $x > -3$ comes from dividing by $-6$ without reversing the inequality direction. The result $x > 3$ comes from both failing to flip the inequality and dropping the negative sign on $-3$, reflecting a concept gap about dividing inequalities by negative numbers. The result $x < 3$ comes from correctly flipping the inequality but losing the negative sign when computing $18 \\div (-6)$, writing $3$ instead of $-3$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EAT4X6', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A scatterplot shows a linear association between the number of hours studied, $x$, and the score on a test, $y$. The line of best fit is $y = 7x + 52$. According to this model, what is the predicted test score for a student who studies for $6$ hours?', NULL, $lyceon_json$[{"key":"A","text":"$42$"},{"key":"B","text":"$87$"},{"key":"C","text":"$94$"},{"key":"D","text":"$101$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $x = 6$ into the equation: $y = 7(6) + 52 = 42 + 52 = 94$. The distractor $42$ computes $7 \\times 6 = 42$ but omits the $y$-intercept of $52$. The distractor $87$ substitutes $x = 5$ instead of $x = 6$: $7(5) + 52 = 87$. The distractor $101$ substitutes $x = 7$ instead of $x = 6$: $7(7) + 52 = 101$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EISYEN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A survey of 200 employees at a company asked whether they commute by car or by train and whether they work in the marketing or engineering department. Of the 200 employees, 74 commute by car and work in marketing, 31 commute by train and work in marketing, 53 commute by car and work in engineering, and 42 commute by train and work in engineering. If an employee who commutes by train is selected at random, what is the probability that this employee works in engineering?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{42}{200}$"},{"key":"B","text":"$\\frac{42}{73}$"},{"key":"C","text":"$\\frac{42}{95}$"},{"key":"D","text":"$\\frac{53}{127}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The question asks for a conditional probability: given the employee commutes by train. The total number of train commuters is $31 + 42 = 73$. Of these, 42 work in engineering, so the probability is $\\frac{42}{73}$. The distractor $\\frac{42}{200}$ uses the total number of employees (200) as the denominator instead of conditioning on train commuters only — a failure to apply the conditional probability definition. The distractor $\\frac{42}{95}$ uses $53 + 42 = 95$ (total engineering employees) as the denominator, confusing the conditioning event with the target event. The distractor $\\frac{53}{127}$ uses the number of car-commuting engineers (53) over the total car commuters ($74 + 53 = 127$), selecting the wrong commute mode entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G0AY90', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A polling organization surveys a random sample of 1,100 voters in a state and reports that $52\\%$ support Measure J, with a margin of error of $\\pm 3$ percentage points at a $95\\%$ confidence level. A political analyst claims that Measure J is certain to pass based on this poll. Which of the following best evaluates the analyst''s claim?', NULL, $lyceon_json$[{"key":"A","text":"The claim is justified because $52\\%$ is a majority."},{"key":"B","text":"The claim is not justified because the confidence interval of $49\\%$ to $55\\%$ includes values below $50\\%$."},{"key":"C","text":"The claim is justified because the sample size of 1,100 is large enough to eliminate uncertainty."},{"key":"D","text":"The claim is not justified because a $95\\%$ confidence level means there is a $5\\%$ chance the true proportion is exactly $50\\%$."}]$lyceon_json$::jsonb, 'B', NULL, E'The confidence interval is $52\\% \\pm 3\\%$, or $49\\%$ to $55\\%$. Because this interval includes values below $50\\%$, it is plausible that fewer than half of all voters support Measure J, so the claim that it is certain to pass is not justified. The distractor that the claim is justified because $52\\%$ is a majority considers only the point estimate and ignores the margin of error, which is partial reasoning. The distractor about the sample size eliminating uncertainty incorrectly assumes that a large sample removes all sampling error — no finite sample eliminates uncertainty entirely. The distractor about a $5\\%$ chance the true proportion is exactly $50\\%$ misinterprets the confidence level: the $5\\%$ refers to the long-run frequency of intervals that fail to capture the true parameter, not to the probability of any specific value.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2H4PEG6', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A basket contains 13 apples: 4 are Fuji, 6 are Gala, and 3 are Honeycrisp. If one apple is selected at random from the basket, what is the probability that it is a Gala apple?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{3}{13}$"},{"key":"B","text":"$\\frac{4}{13}$"},{"key":"C","text":"$\\frac{6}{13}$"},{"key":"D","text":"$\\frac{6}{10}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The total number of apples is $4 + 6 + 3 = 13$. There are 6 Gala apples, so the probability of selecting a Gala apple is $\\frac{6}{13}$. The distractor $\\frac{3}{13}$ results from selecting the Honeycrisp count instead of Gala. The distractor $\\frac{4}{13}$ results from selecting the Fuji count instead of Gala. The distractor $\\frac{6}{10}$ results from incorrectly using $4 + 6 = 10$ as the denominator instead of the total 13, omitting the 3 Honeycrisp apples.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HR9RHW', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'If $f(x) = 7x - 11$, what is the value of $f(5)$?', NULL, $lyceon_json$[{"key":"A","text":"$16$"},{"key":"B","text":"$24$"},{"key":"C","text":"$34$"},{"key":"D","text":"$46$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substitute $x = 5$ into $f(x) = 7x - 11$: $f(5) = 7(5) - 11 = 35 - 11 = 24$. The value $16$ results from computing $7(5) = 35$ but then subtracting $19$ instead of $11$ (arithmetic slip). The value $34$ comes from computing $7(5) = 35$ and then subtracting only $1$ instead of $11$, misreading the constant. The value $46$ results from adding $11$ to $35$ instead of subtracting, a sign error with the constant term.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ISE5OF', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'The equation $x^2 + y^2 - 10x + 4y + 13 = 0$ represents a circle in the $xy$-plane. What is the radius of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$4$"},{"key":"C","text":"$8$"},{"key":"D","text":"$16$"}]$lyceon_json$::jsonb, 'B', NULL, E'Completing the square: group the $x$- and $y$-terms and complete the square for each. $x^2 - 10x + 25 + y^2 + 4y + 4 = -13 + 25 + 4$, which gives $(x - 5)^2 + (y + 2)^2 = 16$. Since the standard form is $(x - h)^2 + (y - k)^2 = r^2$, we have $r^2 = 16$ and $r = 4$. The value $3$ results from an arithmetic error when combining the constants, such as computing $-13 + 25 + 4$ as $20$ and subtracting incorrectly to get $r^2 = 9$. The value $8$ results from finding $r^2 = 16$ and then halving instead of taking the square root. The value $16$ results from correctly finding $r^2 = 16$ but reporting $r^2$ as the radius rather than taking the square root.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JE62SK', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'grid_in', E'In a right triangle, the lengths of the two legs are $20$ and $99$. What is the length of the hypotenuse?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '101', ARRAY['101'], E'By the Pythagorean theorem, the hypotenuse $c$ satisfies $c^2 = 20^2 + 99^2 = 400 + 9801 = 10201$. Taking the square root gives $c = \\sqrt{10201} = 101$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2K2GT4S', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In right triangle $JKL$ with the right angle at $K$, $\\sin(\\angle J) = \\frac{5}{13}$. If $KL = 35$, what is the length of the hypotenuse $\\overline{JL}$?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$84$"},{"key":"C","text":"$91$"},{"key":"D","text":"$455$"}]$lyceon_json$::jsonb, 'C', NULL, E'Since $\\sin(\\angle J) = \\frac{\\text{opposite}}{\\text{hypotenuse}} = \\frac{KL}{JL}$, we have $\\frac{5}{13} = \\frac{35}{JL}$. Cross-multiplying gives $5 \\cdot JL = 13 \\cdot 35 = 455$, so $JL = \\frac{455}{5} = 91$. The value $7$ results from computing only $\\frac{35}{5} = 7$ and stopping before multiplying by $13$. The value $84$ results from using cosine instead of sine to find the adjacent leg ($\\sqrt{91^2 - 35^2} = \\sqrt{7056} = 84$), confusing it with the hypotenuse. The value $455$ results from computing $13 \\times 35 = 455$ but forgetting to divide by $5$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KO8TKW', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'What is the sum of the solutions to the equation $x^2 - 13x + 30 = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '13', ARRAY['13'], E'Factoring the quadratic: $x^2 - 13x + 30 = (x - 3)(x - 10) = 0$. Setting each factor equal to zero gives $x = 3$ or $x = 10$. The sum of the solutions is $3 + 10 = 13$. Alternatively, by Vieta''s formulas, for $x^2 + bx + c = 0$ the sum of the roots equals $-b$. Here $b = -13$, so the sum is $-(-13) = 13$. A common error is computing the product of the roots instead of the sum: $3 \\times 10 = 30$ (misread question). Another error is negating the sum, giving $-13$, from misapplying Vieta''s formula as $b$ rather than $-b$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L1R1C9', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'$$\\sqrt{-2x + 11} = x + 2$$
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L80S8Z', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $PQR$, the exterior angle at vertex $R$ measures $139°$. If $\\angle P = 68°$, what is the measure, in degrees, of $\\angle Q$?', NULL, $lyceon_json$[{"key":"A","text":"$30$"},{"key":"B","text":"$41$"},{"key":"C","text":"$71$"},{"key":"D","text":"$112$"}]$lyceon_json$::jsonb, 'C', NULL, E'By the Exterior Angle Theorem, the exterior angle at a vertex equals the sum of the two remote interior angles. Thus $139 = 68 + \\angle Q$, giving $\\angle Q = 71°$. The value $30$ results from incorrectly setting the exterior angle equal to the sum of all three interior angles: $139 = 68 + Q + (180 - 139)$, which gives $Q = 30$. The value $41$ comes from computing the interior angle at $R$ ($180 - 139 = 41$) and reporting that instead of $\\angle Q$. The value $112$ comes from computing $180 - 68 = 112$, ignoring the exterior angle information entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LIX5K5', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'mcq', E'A circle has a radius of $6$ units. What is the length of an arc subtended by a central angle of $150°$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{5\\pi}{6}$"},{"key":"B","text":"$\\frac{5\\pi}{2}$"},{"key":"C","text":"$5\\pi$"},{"key":"D","text":"$15\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'Arc length equals the fraction of the full circumference: $\\frac{150}{360} \\times 2\\pi(6) = \\frac{5}{12} \\times 12\\pi = 5\\pi$. The value $\\frac{5\\pi}{6}$ results from converting $150°$ to radians ($\\frac{5\\pi}{6}$) and reporting the angle measure as the arc length without multiplying by the radius. The value $\\frac{5\\pi}{2}$ results from using $\\pi r$ instead of $2\\pi r$ for the circumference: $\\frac{5}{12} \\times 6\\pi = \\frac{5\\pi}{2}$. The value $15\\pi$ results from using the sector area formula $\\frac{150}{360} \\times \\pi r^2 = \\frac{5}{12} \\times 36\\pi = 15\\pi$ instead of the arc length formula.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LUEA1E', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher collects data on the number of rainy days per month, $x$, and the number of umbrellas sold per month, $y$, in a city over several months. The line of best fit is $y = 11x + 29$. In this context, what does the slope of the line represent?', NULL, $lyceon_json$[{"key":"A","text":"The predicted number of umbrellas sold when there are no rainy days"},{"key":"B","text":"For each additional rainy day, umbrella sales are predicted to increase by $11$"},{"key":"C","text":"For each additional umbrella sold, the number of rainy days is predicted to increase by $11$"},{"key":"D","text":"The total number of umbrellas predicted to be sold over $11$ rainy days"}]$lyceon_json$::jsonb, 'B', NULL, E'The slope of a linear model represents the predicted change in the dependent variable ($y$, umbrella sales) for each one-unit increase in the independent variable ($x$, rainy days). Here the slope of $11$ means umbrella sales are predicted to increase by $11$ for each additional rainy day. The distractor describing the prediction when there are no rainy days interprets the $y$-intercept ($29$), not the slope. The distractor reversing the variables incorrectly treats $x$ as dependent on $y$. The distractor about total sales over $11$ rainy days confuses the slope with a specific prediction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LYAARP', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'For an acute angle $\\theta$, $\\sin(\\theta) = \\frac{7}{25}$. What is the value of $\\frac{1}{\\cos\\theta} - \\sin\\theta \\cdot \\tan\\theta$?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{7}{25}$"},{"key":"B","text":"$\\frac{7}{24}$"},{"key":"C","text":"$\\frac{24}{25}$"},{"key":"D","text":"$\\frac{25}{24}$"}]$lyceon_json$::jsonb, 'C', NULL, E'The expression simplifies algebraically: $\\frac{1}{\\cos\\theta} - \\sin\\theta \\cdot \\tan\\theta = \\frac{1}{\\cos\\theta} - \\frac{\\sin^2\\theta}{\\cos\\theta} = \\frac{1 - \\sin^2\\theta}{\\cos\\theta} = \\frac{\\cos^2\\theta}{\\cos\\theta} = \\cos\\theta$. With $\\sin\\theta = \\frac{7}{25}$, the adjacent side is $\\sqrt{25^2 - 7^2} = \\sqrt{576} = 24$, so $\\cos\\theta = \\frac{24}{25}$. The value $\\frac{7}{25}$ results from returning $\\sin\\theta$ instead of $\\cos\\theta$, confusing the two functions. The value $\\frac{7}{24}$ results from computing $\\tan\\theta$ and presenting it as the answer, confusing the expression with a single trig ratio. The value $\\frac{25}{24}$ results from computing only $\\frac{1}{\\cos\\theta} = \\sec\\theta$ and stopping before subtracting the second term.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M4106T', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of 400 residents in a city found that $37\\%$ plan to vote for Candidate X in the upcoming election. The margin of error for the survey is $\\pm 4$ percentage points. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Exactly $37\\%$ of all city residents plan to vote for Candidate X."},{"key":"B","text":"Between $33\\%$ and $41\\%$ of all city residents are plausibly planning to vote for Candidate X."},{"key":"C","text":"Between $33\\%$ and $41\\%$ of the 400 sampled residents plan to vote for Candidate X."},{"key":"D","text":"If the survey were repeated, $37\\%$ of the new sample would plan to vote for Candidate X."}]$lyceon_json$::jsonb, 'B', NULL, E'A margin of error of $\\pm 4$ percentage points around $37\\%$ means the plausible range for the true population proportion is $37\\% - 4\\% = 33\\%$ to $37\\% + 4\\% = 41\\%$. The interval applies to the population, not the sample. The distractor stating exactly $37\\%$ ignores the margin of error entirely, treating a sample statistic as exact. The distractor applying the interval to the 400 sampled residents misapplies the concept — the margin of error describes uncertainty about the population parameter, not the sample result (which is already known). The distractor about repeating the survey confuses sampling variability with the confidence interval interpretation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MYFSGE', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'grid_in', E'The mean of a list of $9$ consecutive odd integers is $41$. What is the range of this list?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '16', ARRAY['16'], E'For $9$ consecutive odd integers with a mean of $41$, the middle (5th) value equals the mean, so the $5$th integer is $41$. The full list is $33, 35, 37, 39, 41, 43, 45, 47, 49$. The range is $49 - 33 = 16$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2N7O47O', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $\\frac{64x^2 - 9}{8x + 3}$, where $8x + 3 \\neq 0$?', NULL, $lyceon_json$[{"key":"A","text":"$8x - 3$"},{"key":"B","text":"$8x + 3$"},{"key":"C","text":"$8x - 9$"},{"key":"D","text":"$64x - 3$"}]$lyceon_json$::jsonb, 'A', NULL, E'The numerator $64x^2 - 9$ is a difference of squares: $(8x)^2 - 3^2 = (8x + 3)(8x - 3)$. Dividing by $(8x + 3)$ cancels the common factor, leaving $8x - 3$. The distractor $8x + 3$ results from a sign error when applying the difference of squares pattern, incorrectly writing both factors as $(8x + 3)$. The distractor $8x - 9$ comes from incorrectly leaving $-9$ rather than $-3$ after factoring, as if only the $x$-term were affected by the factorization. The distractor $64x - 3$ results from dividing $64x^2$ by just $x$ instead of by $(8x + 3)$, and dividing $-9$ by $3$ to get $-3$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NJALHK', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'A mechanic charges a flat diagnostic fee of $\\$47$ plus $\\$29$ per hour of labor. If the total bill for a repair was $\\$221$, how many hours of labor did the mechanic work?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$6$"},{"key":"C","text":"$7$"},{"key":"D","text":"$8$"}]$lyceon_json$::jsonb, 'B', NULL, E'Set up the equation $47 + 29h = 221$. Subtract $47$ from both sides: $29h = 174$. Divide by $29$: $h = 6$. The value $5$ results from a computational error such as dividing $174$ by $30$ instead of $29$ and rounding. The value $7$ results from omitting the flat fee and computing $221 \\div 29 \\approx 7.6$, then rounding down. The value $8$ results from dividing $221$ by $29$ and rounding up, also ignoring the flat fee.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NMQCZS', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'The ages, in years, of $7$ members of a hiking club are $19$, $23$, $29$, $34$, $37$, $41$, and $46$. What is the median age of the club members?', NULL, $lyceon_json$[{"key":"A","text":"$29$"},{"key":"B","text":"$32.5$"},{"key":"C","text":"$34$"},{"key":"D","text":"$37$"}]$lyceon_json$::jsonb, 'C', NULL, E'With $7$ values listed in order, the median is the $4$th value, which is $34$. The distractor $29$ selects the $3$rd value, one position before the middle. The distractor $32.5$ computes the midrange $\\frac{19 + 46}{2} = 32.5$, confusing midrange with median. The distractor $37$ selects the $5$th value, one position after the middle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2O66IY5', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $h$ is defined by $h(x) = -3(x - 7)^2 + k$, where $k$ is a constant. If $h(4) = -54$, what is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$-81$"},{"key":"B","text":"$-27$"},{"key":"C","text":"$27$"},{"key":"D","text":"$-54$"}]$lyceon_json$::jsonb, 'B', NULL, E'Substituting $x = 4$ into $h(x) = -3(x - 7)^2 + k$: $h(4) = -3(4 - 7)^2 + k = -3(-3)^2 + k = -3(9) + k = -27 + k$. Setting this equal to $-54$: $-27 + k = -54$, so $k = -54 + 27 = -27$. The distractor $-81$ results from incorrectly adding $-27$ and $-54$ together ($-27 + (-54) = -81$) instead of solving for $k$. The distractor $27$ comes from a sign error, computing $k = 54 - 27 = 27$ by incorrectly treating $-54$ as positive. The distractor $-54$ arises from assuming $k$ equals the given function value $h(4) = -54$ without performing the substitution.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OAPE6Q', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'A bakery makes sourdough and rye bread. Each loaf of sourdough requires $3$ cups of flour, and each loaf of rye requires $5$ cups. The bakery has at most $85$ cups of flour available and must bake at least $7$ loaves of rye to fulfill standing orders. What is the maximum number of sourdough loaves the bakery can make?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '16', ARRAY['16'], E'Let $s$ represent sourdough loaves and $r$ represent rye loaves. The constraints are $3s + 5r \\leq 85$ and $r \\geq 7$. To maximize $s$, minimize $r$ at its lower bound: $r = 7$. Substituting: $3s + 5(7) \\leq 85$, so $3s + 35 \\leq 85$, giving $3s \\leq 50$, hence $s \\leq 16.\\overline{6}$. Since $s$ must be a whole number, the maximum is $16$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ON51AK', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'What is the greatest integer value of $x$ that satisfies $6x - 5 \\leq 37$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$6$"},{"key":"C","text":"$7$"},{"key":"D","text":"$8$"}]$lyceon_json$::jsonb, 'C', NULL, E'Solving $6x - 5 \\leq 37$: add $5$ to both sides to get $6x \\leq 42$, then divide by $6$ to get $x \\leq 7$. The greatest integer satisfying this is $7$. The value $5$ results from an arithmetic slip: subtracting $7$ from $37$ instead of adding $5$ (getting $6x \\leq 30$, so $x \\leq 5$). The value $6$ results from partial reasoning: skipping the step of adding $5$, so $6x \\leq 37$ gives $x \\leq 6.17$, and the greatest integer is taken as $6$. The value $8$ results from a sign error: mistakenly subtracting $5$ from the right side instead of adding it ($6x \\leq 37 - 5 = 32$), then computing $32 \\div 6 \\approx 5.3$ but misapplying ceiling rounding to get $8$ by adding the subtracted $5$ back as a correction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P2BOTX', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'mcq', E'If $11x + 7 = 84$, what is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$7$"},{"key":"C","text":"$8$"},{"key":"D","text":"$\\frac{84}{11}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Subtract $7$ from both sides to get $11x = 77$. Divide both sides by $11$ to get $x = 7$. The value $6$ results from incorrectly computing $77 \\div 11$ as $6$ (arithmetic slip). The value $8$ comes from computing $84 \\div 11 \\approx 7.6$ and rounding up. The value $\\frac{84}{11}$ results from dividing $84$ by $11$ directly without first subtracting $7$, an equation setup error.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P2CRI1', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a radius of $11$ units. What is the area of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$11\\pi$"},{"key":"B","text":"$22\\pi$"},{"key":"C","text":"$121\\pi$"},{"key":"D","text":"$242\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The area of a circle is $A = \\pi r^2 = \\pi(11)^2 = 121\\pi$. The value $11\\pi$ results from using $\\pi r$ instead of $\\pi r^2$, omitting the squaring step. The value $22\\pi$ results from computing the circumference $2\\pi r = 2\\pi(11) = 22\\pi$ instead of the area. The value $242\\pi$ results from computing $2\\pi r^2 = 2(121)\\pi = 242\\pi$, incorrectly doubling the area formula.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q20N98', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'Two angles form a linear pair. If one angle measures $47°$, what is the measure, in degrees, of the other angle?', NULL, $lyceon_json$[{"key":"A","text":"$43$"},{"key":"B","text":"$94$"},{"key":"C","text":"$133$"},{"key":"D","text":"$137$"}]$lyceon_json$::jsonb, 'C', NULL, E'A linear pair of angles is supplementary, meaning the two angles sum to $180°$. Subtracting gives $180 - 47 = 133$. The value $43$ results from subtracting from $90°$ instead of $180°$, confusing supplementary with complementary angles. The value $94$ results from doubling $47$ instead of subtracting from $180°$. The value $137$ results from an arithmetic error such as misreading $47$ as $43$ and computing $180 - 43$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q747YZ', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $g$ is defined by $g(x) = 2x^2 - 20x + 53$. For what value of $x$ does $g(x)$ reach its minimum?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$5$"},{"key":"C","text":"$10$"},{"key":"D","text":"$53$"}]$lyceon_json$::jsonb, 'B', NULL, E'The $x$-coordinate of the vertex of $g(x) = 2x^2 - 20x + 53$ is found using $x = -\\frac{b}{2a} = -\\frac{-20}{2(2)} = \\frac{20}{4} = 5$. The distractor $3$ results from computing the minimum value $g(5) = 2(25) - 100 + 53 = 3$ rather than the $x$-value where the minimum occurs. The distractor $10$ arises from forgetting to divide by $2a$ and instead computing $-\\frac{b}{a} = \\frac{20}{2} = 10$. The distractor $53$ comes from selecting the constant term of the quadratic, confusing it with the answer.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q810C8', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveys a random sample of 600 high school students in a state and finds that $43\\%$ participate in at least one extracurricular activity. The margin of error is $\\pm 3$ percentage points at a $95\\%$ confidence level. A second researcher surveys a random sample of 150 students from the same state and also finds that $43\\%$ participate. If the second survey uses the same confidence level, which of the following best compares the margins of error?', NULL, $lyceon_json$[{"key":"A","text":"The second survey has a smaller margin of error because its sample is more focused."},{"key":"B","text":"The two surveys have the same margin of error because they found the same sample proportion."},{"key":"C","text":"The second survey has a larger margin of error because its sample size is smaller."},{"key":"D","text":"The margins of error cannot be compared without knowing the total number of students in the state."}]$lyceon_json$::jsonb, 'C', NULL, E'The margin of error is inversely related to the square root of the sample size: as sample size decreases, the margin of error increases, all else being equal. Since both surveys use the same confidence level and found the same proportion, the survey with 150 students will have a larger margin of error than the one with 600 students. The distractor claiming a smaller margin of error reverses the relationship between sample size and precision. The distractor claiming equal margins of error confuses the sample statistic (which happens to be the same) with the margin of error, which depends on sample size, not on the observed proportion alone. The distractor about needing the total population size is incorrect because for large populations, the margin of error depends on sample size, not population size (the finite population correction is negligible when the sample is a small fraction of the population).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Q8EVL6', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'grid_in', E'$$2(3x + 7) - 5(x - 4) = 3(x + 11) - 2$$ What is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3/2', ARRAY['3/2', '1.5'], E'Distribute on the left side: $6x + 14 - 5x + 20 = x + 34$. Distribute on the right side: $3x + 33 - 2 = 3x + 31$. The equation becomes $x + 34 = 3x + 31$. Subtract $x$ from both sides: $34 = 2x + 31$. Subtract $31$: $3 = 2x$. Divide by $2$: $x = \\frac{3}{2}$. A common error is distributing the $-5$ incorrectly as $-5x - 20$ instead of $-5x + 20$, which yields $x - 6 = 3x + 31$ and then $x = -\\frac{37}{2}$ (sign error in distribution). Another error is forgetting to distribute the $2$ across both terms, treating the left side as $6x + 7 - 5x + 4 = x + 11$, giving $x + 11 = 3x + 31$ and $x = -10$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QW8XWF', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A triangle has a base of $22$ units and a height of $13$ units. What is the area, in square units, of the triangle?', NULL, $lyceon_json$[{"key":"A","text":"$35$"},{"key":"B","text":"$143$"},{"key":"C","text":"$286$"},{"key":"D","text":"$572$"}]$lyceon_json$::jsonb, 'B', NULL, E'The area of a triangle is $A = \\frac{1}{2} \\times \\text{base} \\times \\text{height} = \\frac{1}{2} \\times 22 \\times 13 = 143$. The value $35$ results from adding the base and height ($22 + 13 = 35$) instead of using the area formula. The value $286$ results from computing $22 \\times 13 = 286$ but forgetting to multiply by $\\frac{1}{2}$. The value $572$ results from doubling instead of halving the product, computing $22 \\times 13 \\times 2 = 572$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QZJKHI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A health researcher finds that among 2,300 adults in a city, those who reported drinking green tea daily had lower average blood pressure than those who did not drink green tea. No random assignment was used; participants self-selected into tea-drinking or non-tea-drinking groups. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Drinking green tea causes lower blood pressure in adults."},{"key":"B","text":"There is an association between daily green tea consumption and lower blood pressure, but a causal relationship cannot be established."},{"key":"C","text":"The study proves that not drinking green tea raises blood pressure."},{"key":"D","text":"The sample size of 2,300 is too small to draw any conclusion."}]$lyceon_json$::jsonb, 'B', NULL, E'Because participants self-selected into groups rather than being randomly assigned, this is an observational study. Observational studies can establish associations but cannot establish causation, since confounding variables (such as overall healthier lifestyles among tea drinkers) may explain the difference. The distractor claiming green tea causes lower blood pressure incorrectly draws a causal conclusion from an observational study. The distractor claiming the study proves not drinking tea raises blood pressure reverses the direction and incorrectly claims proof of causation. The distractor about sample size is incorrect because 2,300 is a substantial sample; the limitation is the study design (lack of random assignment), not the sample size.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RE3UZ0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A paint mixture requires $7$ parts blue paint for every $3$ parts white paint. If a painter uses $21$ parts of white paint, how many parts of blue paint are needed?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$28$"},{"key":"C","text":"$49$"},{"key":"D","text":"$63$"}]$lyceon_json$::jsonb, 'C', NULL, E'The ratio of blue to white paint is $7:3$. Setting up the proportion $\\frac{7}{3} = \\frac{x}{21}$ gives $x = 7 \\times 7 = 49$. The distractor $9$ results from inverting the ratio and computing $\\frac{3}{7} \\times 21 = 9$. The distractor $28$ comes from adding $7$ to $21$ instead of using the proportional relationship. The distractor $63$ results from multiplying $21 \\times 3$ (the white-paint ratio number) instead of using $\\frac{7}{3}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RNAP51', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle $DEF$, point $G$ lies on $\\overline{EF}$ such that $\\overline{DG}$ bisects $\\angle EDF$. If $\\angle DEF = 74°$ and $\\angle DFE = 38°$, what is the measure, in degrees, of $\\angle DGE$?', NULL, $lyceon_json$[{"key":"A","text":"$68$"},{"key":"B","text":"$72$"},{"key":"C","text":"$74$"},{"key":"D","text":"$108$"}]$lyceon_json$::jsonb, 'B', NULL, E'First, find $\\angle EDF = 180 - 74 - 38 = 68°$. Since $\\overline{DG}$ bisects $\\angle EDF$, we have $\\angle EDG = 34°$. In triangle $DEG$, the angle sum gives $\\angle DGE = 180 - 74 - 34 = 72°$. The value $68$ results from stopping after computing $\\angle EDF$ without continuing to find the bisected angle and applying it in triangle $DEG$. The value $74$ results from misidentifying the requested angle and reporting $\\angle DEF$ instead. The value $108$ results from computing the supplement of the correct answer ($180 - 72$), confusing $\\angle DGE$ with its supplementary angle $\\angle DGF$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RQ0FPC', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A linear function $f$ satisfies $f(2) = 17$ and $f(8) = 47$. What is the rate of change of $f$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$5$"},{"key":"C","text":"$6$"},{"key":"D","text":"$10$"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate of change of a linear function is the slope: $\\frac{f(8) - f(2)}{8 - 2} = \\frac{47 - 17}{6} = \\frac{30}{6} = 5$. The value $3$ results from computing $\\frac{47 - 17}{8 + 2} = \\frac{30}{10} = 3$, adding the $x$-values instead of subtracting (arithmetic slip in the denominator). The value $6$ comes from inverting the fraction and computing $\\frac{8 - 2}{47 - 17} = \\frac{6}{30} = \\frac{1}{5}$, but then misreading the result as $6$ (the denominator difference). The value $10$ results from using only the difference $47 - 17 = 30$ and dividing by $3$ (perhaps confusing $f(2) = 17$ as having $x = 3$) or from a partial calculation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RU1ATJ', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'The function $g$ is defined by $g(x) = ax + b$, where $a$ and $b$ are constants. If $g(3) = 22$ and $g(7) = 46$, for what value of $x$ does $g(x) = 100$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '16', ARRAY['16'], E'Find the slope: $a = \\frac{g(7) - g(3)}{7 - 3} = \\frac{46 - 22}{4} = \\frac{24}{4} = 6$. Substitute into $g(3) = 22$: $6(3) + b = 22$, so $18 + b = 22$ and $b = 4$. The function is $g(x) = 6x + 4$. Set $g(x) = 100$: $6x + 4 = 100$, so $6x = 96$ and $x = 16$. A common error is finding the slope correctly but computing $b$ from $g(7)$: $46 - 6(7) = 46 - 42 = 4$, which actually also yields $b = 4$ (consistent), but a sign slip such as $46 - 6(3) = 46 - 18 = 28$ (using the wrong point''s $x$ with the other point''s output) gives $b = 28$ and then $6x + 28 = 100$, yielding $x = 12$. Another error is solving $6x + 4 = 100$ as $6x = 104$ (adding $4$ instead of subtracting), giving $x = \\frac{104}{6} \\approx 17.3$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T9KOBI', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A pair of running shoes originally costs $\\$85$. During a sale, the price is reduced by $40\\%$. What is the sale price of the running shoes?', NULL, $lyceon_json$[{"key":"A","text":"$\\$34$"},{"key":"B","text":"$\\$45$"},{"key":"C","text":"$\\$51$"},{"key":"D","text":"$\\$68$"}]$lyceon_json$::jsonb, 'C', NULL, E'The discount is $85 \\times 0.40 = 34$, so the sale price is $85 - 34 = 51$ dollars. The distractor $\\$34$ gives the discount amount rather than the sale price. The distractor $\\$45$ subtracts $40$ from $85$ as though $40\\%$ means $40$ dollars. The distractor $\\$68$ computes $85 \\times 0.80 = 68$, applying a $20\\%$ discount instead of $40\\%$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TWM4S1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'grid_in', E'A delivery truck uses $13$ gallons of fuel to travel $221$ miles. At the same rate, how many miles can the truck travel on $29$ gallons of fuel?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '493', ARRAY['493'], E'The truck''s fuel efficiency is $\\frac{221}{13} = 17$ miles per gallon. On $29$ gallons, the truck can travel $17 \\times 29 = 493$ miles.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UOEUKX', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'grid_in', E'Line $\\ell$ is perpendicular to the line $5x - 3y = 9$ and passes through the point $(6, -1)$. What is the $y$-intercept of line $\\ell$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '13/5', ARRAY['13/5', '2.6'], E'Rewrite $5x - 3y = 9$ in slope-intercept form: $y = \\frac{5}{3}x - 3$, so the slope is $\\frac{5}{3}$. The slope of a perpendicular line is the negative reciprocal: $-\\frac{3}{5}$. Use point-slope form with $(6, -1)$: $y - (-1) = -\\frac{3}{5}(x - 6)$. Simplify: $y + 1 = -\\frac{3}{5}x + \\frac{18}{5}$. Then $y = -\\frac{3}{5}x + \\frac{18}{5} - 1 = -\\frac{3}{5}x + \\frac{13}{5}$. The $y$-intercept is $\\frac{13}{5}$. A common error is using the same slope $\\frac{5}{3}$ instead of the negative reciprocal, which gives a $y$-intercept of $-1 - \\frac{5}{3}(6) = -11$ (concept gap about perpendicular slopes). Another error is computing the negative reciprocal as $\\frac{3}{5}$ (positive) instead of $-\\frac{3}{5}$, yielding a $y$-intercept of $-1 - \\frac{18}{5} = -\\frac{23}{5}$ (sign error).', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UTYU77', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'mcq', E'How many distinct real solutions does the equation $3x^2 - 7x + 5 = 0$ have?', NULL, $lyceon_json$[{"key":"A","text":"$0$"},{"key":"B","text":"$1$"},{"key":"C","text":"$2$"},{"key":"D","text":"$3$"}]$lyceon_json$::jsonb, 'A', NULL, E'The discriminant is $b^2 - 4ac = (-7)^2 - 4(3)(5) = 49 - 60 = -11$. Since the discriminant is negative, the equation has zero distinct real solutions. The distractor $1$ results from confusing a negative discriminant with a zero discriminant, which would indicate exactly one repeated real root. The distractor $2$ comes from assuming every quadratic equation has two real roots without checking the discriminant. The distractor $3$ arises from confusing the leading coefficient $3$ with the number of solutions or misreading the problem as a cubic equation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2Z7RBHV', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'grid_in', E'The solution to the system of equations $4x + 7y = 59$ and $4x - 3y = 9$ is $(x, y)$. What is the value of $x + y$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '11', ARRAY['11'], E'Subtract the second equation from the first: $(4x + 7y) - (4x - 3y) = 59 - 9$, giving $10y = 50$, so $y = 5$. Substitute into the second equation: $4x - 15 = 9$, so $4x = 24$ and $x = 6$. Therefore $x + y = 6 + 5 = 11$.', NULL, NULL, 'draft', 1, 85, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZPFX0S', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'mcq', E'If $\\frac{7x^3 + 14x^2 - 21x}{7x}$ is rewritten in the form $x^2 + bx + c$, where $x \\neq 0$, what is the value of $b - c$?', NULL, $lyceon_json$[{"key":"A","text":"$5$"},{"key":"B","text":"$-1$"},{"key":"C","text":"$1$"},{"key":"D","text":"$-5$"}]$lyceon_json$::jsonb, 'A', NULL, E'Dividing each term of $7x^3 + 14x^2 - 21x$ by $7x$: $\\frac{7x^3}{7x} = x^2$, $\\frac{14x^2}{7x} = 2x$, and $\\frac{-21x}{7x} = -3$. So the expression equals $x^2 + 2x - 3$, giving $b = 2$ and $c = -3$. Therefore $b - c = 2 - (-3) = 5$. The distractor $-1$ comes from computing $b + c = 2 + (-3) = -1$ instead of $b - c$. The distractor $1$ arises from treating $c$ as positive $3$ instead of $-3$, giving $b - c = 2 - 3 = -1$, and then taking its absolute value. The distractor $-5$ results from computing $c - b = -3 - 2 = -5$ instead of $b - c$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20AXG4F', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Guiana highlands of Venezuela contain some of the oldest geological formations on Earth. Mount Roraima, a flat-topped mountain rising over 2,700 meters, ______ scientists who study its unique ecosystem have cataloged more than 130 species of plants found nowhere else in the world.', $lyceon_json$[{"key":"A","text":"is particularly notable:"},{"key":"B","text":"is particularly notable, and"},{"key":"C","text":"is particularly notable"},{"key":"D","text":"is particularly notable,"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence requires a punctuation mark that introduces an explanatory clause. A colon correctly signals that what follows elaborates on why the mountain is notable. The option using a comma and coordinating conjunction creates a grammatically awkward structure because the clause after it is an independent statement about scientists, not a continuation of the same subject. The option with no punctuation produces a run-on sentence. The option with only a comma creates a comma splice between two independent clauses.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21OHQZS', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'A team of marine biologists studying coral bleaching patterns across seventeen Pacific atolls published a landmark report in 2023. The evidence gathered over a nine-year observation period ______ that sustained ocean temperature increases of even 1.3 degrees Celsius above historical averages can trigger irreversible colony collapse in branching corals.', $lyceon_json$[{"key":"A","text":"indicates"},{"key":"B","text":"indicate"},{"key":"C","text":"are indicating"},{"key":"D","text":"have indicated"}]$lyceon_json$::jsonb, 'A', NULL, E'The subject is the singular uncountable noun ''evidence,'' which requires a singular verb regardless of the intervening prepositional phrase ''gathered over a nine-year observation period.'' The singular present-tense ''indicates'' correctly agrees with this subject. The plural form ''indicate'' incorrectly treats ''evidence'' as plural, likely attracted by the nearby plural noun ''atolls'' or the prepositional phrase. The plural progressive ''are indicating'' uses a plural auxiliary that does not agree with the singular subject. The plural perfect ''have indicated'' similarly fails to agree with the singular uncountable ''evidence.''', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21Y8DEH', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes the relationship between the two texts?', E'Text 1: Literary historian Priya Venkatesh argues that the serialized novels published in nineteenth-century Indian periodicals should be understood primarily as commercial products. Publishers, Venkatesh notes, deliberately introduced cliffhangers and subplots to sustain subscriptions, and authors frequently altered storylines in response to reader correspondence, suggesting that market forces shaped narrative structure more decisively than artistic intention.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22SXQX2', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a food historian would best support the claim made in the text?', E'Culinary anthropologist Tomás Herrera argues that the widespread adoption of chili peppers in Southeast Asian cuisines after the sixteenth century was driven less by flavor preference than by the practical advantages chili peppers offered to subsistence farmers. Unlike black pepper and other established spices, chili plants could be grown in small household gardens with minimal labor, producing abundant fruit across multiple harvests per year. Herrera claims this economic accessibility, rather than taste alone, explains why chilies displaced costlier spices in everyday cooking across the region.', $lyceon_json$[{"key":"A","text":"\"In seventeenth-century Siam, royal court recipes continued to favor long pepper and galangal, suggesting that chili adoption began among rural households rather than elites.\""},{"key":"B","text":"\"Portuguese traders introduced chili seeds to coastal trading posts in the Malay Archipelago as early as 1513, making Southeast Asia one of the first regions outside the Americas to encounter the plant.\""},{"key":"C","text":"\"Modern sensory studies confirm that capsaicin, the compound responsible for chili heat, activates pain receptors rather than taste receptors, complicating the idea that people adopted chilies primarily for their flavor.\""},{"key":"D","text":"\"Chili peppers contain high concentrations of vitamin C, which may have provided nutritional benefits to populations with limited access to fresh fruit.\""}]$lyceon_json$::jsonb, 'A', NULL, E'Herrera''s claim is that economic accessibility, not taste, drove chili adoption among subsistence farmers. The quotation about royal courts continuing to favor costlier spices while adoption began among rural households directly supports the idea that practical economics rather than flavor preference motivated the shift. The quotation about Portuguese traders introducing chili seeds provides historical context about when chilies arrived but does not address why they were adopted. The quotation about capsaicin activating pain receptors relates to the sensory experience of chilies but does not support the specific economic-accessibility argument Herrera makes. The quotation about vitamin C content introduces a nutritional benefit not discussed in Herrera''s argument, which focuses on ease of cultivation and cost.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24EYZ3X', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second paragraph in relation to the first?', E'Geochemist Mira Patel''s 2021 analysis of strontium isotope ratios in Bronze Age cattle teeth from southeastern Turkey suggested that herders in the region practiced a form of seasonal transhumance, moving livestock between lowland winter pastures and highland summer grazing areas separated by over 170 kilometers.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24XL1FS', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Researchers at the University of Tromsø have found that reindeer in Arctic Norway adjust their circadian rhythms dramatically across seasons. During the polar summer, when sunlight persists for nearly 73 consecutive days, reindeer show no measurable day-night activity cycle. Instead, they feed and rest in short, irregular bouts throughout the 24-hour period. In winter darkness, they similarly lack a fixed schedule, though their total activity decreases. The researchers propose that abandoning a rigid internal clock allows reindeer to maximize foraging opportunities in an environment where light cues are absent for months at a time.', $lyceon_json$[{"key":"A","text":"Reindeer in Arctic Norway have evolved to abandon strict circadian rhythms, which helps them adapt to extreme seasonal light conditions."},{"key":"B","text":"Reindeer are the only Arctic mammals that remain active during the polar night rather than hibernating."},{"key":"C","text":"Researchers at the University of Tromsø discovered that reindeer sleep significantly more during winter darkness than during summer."},{"key":"D","text":"The absence of sunlight in Arctic winters forces reindeer to migrate southward to maintain regular feeding schedules."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes how reindeer abandon rigid circadian rhythms in response to extreme Arctic light conditions, allowing them to maximize foraging. The option stating that reindeer evolved to abandon strict circadian rhythms to adapt to extreme seasonal light conditions captures this central idea. The claim that reindeer are the only Arctic mammals to remain active during polar night introduces unsupported exclusivity not present in the passage. The claim that reindeer sleep significantly more in winter misrepresents the passage, which says total activity decreases but does not equate this with significantly more sleep. The suggestion that reindeer migrate southward contradicts the passage, which describes behavioral adaptation in place, not migration.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28EFBYA', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Based on the text, what can most reasonably be inferred about the glass frogs studied?', E'Biologist Jésica Forero and her colleagues examined how glass frogs (family Centrolenidae) in the Colombian Andes achieve their remarkable translucency. Using photoacoustic imaging, the team found that when glass frogs sleep during the day, they remove nearly 89 percent of their red blood cells from active circulation and pack them into their liver, which becomes a dense, opaque organ. When the frogs wake at night, the red blood cells re-enter the bloodstream, and the frogs'' translucency diminishes. Forero notes that this mechanism is surprising because, in most vertebrates, concentrating such a high proportion of red blood cells in one organ would trigger dangerous blood clotting.', $lyceon_json$[{"key":"A","text":"Glass frogs possess a physiological mechanism that prevents the blood clotting that would normally result from concentrating red blood cells in a single organ."},{"key":"B","text":"Glass frogs are the only vertebrates capable of temporarily removing red blood cells from circulation without fatal consequences."},{"key":"C","text":"Glass frogs evolved their translucency primarily as a defense against predators that hunt using visual cues during daylight hours."},{"key":"D","text":"Glass frogs maintain a constant level of translucency throughout both day and night activity cycles."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that concentrating a high proportion of red blood cells in one organ would normally trigger dangerous blood clotting in most vertebrates, yet glass frogs do this regularly without apparent harm. It can reasonably be inferred that glass frogs have some mechanism preventing this clotting. The claim that glass frogs are the only vertebrates capable of this introduces an unsupported exclusive claim not found in the passage. The assertion about evolving translucency primarily as a predator defense goes beyond the passage, which describes the mechanism of translucency but does not discuss its evolutionary purpose. The claim that glass frogs maintain constant translucency directly contradicts the passage, which states translucency diminishes when the frogs are active at night.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29AUVRK', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Regarded as one of the most versatile polymers ever synthesized, polyethylene terephthalate — commonly known as PET — can be recycled into fibers for clothing, containers for food storage, and components for automotive ______ the recycling process for PET requires significantly less energy than producing the polymer from raw petroleum derivatives.', $lyceon_json$[{"key":"A","text":"parts. Moreover,"},{"key":"B","text":"parts, moreover,"},{"key":"C","text":"parts; consequently,"},{"key":"D","text":"parts, and consequently,"}]$lyceon_json$::jsonb, 'A', NULL, E'Two independent clauses require a clear sentence boundary. A period followed by the conjunctive adverb ''Moreover'' with a comma correctly separates the clauses and signals that the second clause adds further supporting information about PET''s advantages. The option using a comma before ''moreover'' creates a comma splice between two independent clauses. The option using a semicolon with ''consequently'' provides a correct boundary mechanism but uses a logically wrong connector: the second clause does not describe a result or consequence of PET''s versatility but rather an additional, independent advantage of the polymer. Similarly, the option using a comma with ''and consequently'' mischaracterizes the logical relationship as cause-and-effect when the two clauses present parallel but independent merits.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2C5NWPX', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1: Urban planner Deshawn Kato has argued that converting vacant commercial lots into community gardens produces measurable improvements in neighborhood cohesion. In a 2022 survey of 14 cities, Kato found that blocks with community gardens reported 37 percent higher rates of mutual aid among residents compared with blocks that lacked such spaces.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CDHICS', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'Literary scholar Priya Chandrasekaran argues that the critical reception of Zora Neale Hurston''s 1937 novel Their Eyes Were Watching God reflects broader tensions in African American intellectual life during the 1930s. Contemporary reviewers such as Richard Wright faulted the novel for lacking explicit political protest, viewing its focus on a Black woman''s personal journey toward self-fulfillment as a retreat from the urgent social realism they believed Black literature should pursue. Chandrasekaran contends, however, that this criticism rested on a narrow definition of political engagement — one that privileged collective action over individual interiority. She points out that Hurston''s depiction of Janie Crawford''s growing autonomy implicitly challenged the patriarchal structures within both Black and white communities, constituting a form of political expression that Wright''s framework could not accommodate.', $lyceon_json$[{"key":"A","text":"Chandrasekaran argues that early criticism of Hurston's novel stemmed from a restrictive view of political engagement that failed to recognize the political dimensions of depicting individual autonomy."},{"key":"B","text":"Chandrasekaran demonstrates that Richard Wright eventually revised his negative assessment of Their Eyes Were Watching God after recognizing its feminist themes."},{"key":"C","text":"Chandrasekaran claims that Hurston deliberately avoided political themes in her fiction because she disagreed with the social realist movement of the 1930s."},{"key":"D","text":"Chandrasekaran suggests that Their Eyes Were Watching God was initially praised by most critics but later fell out of favor due to changing literary standards."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents Chandrasekaran''s argument that Wright and other critics applied a narrow definition of political engagement when faulting Hurston''s novel, missing the political implications of depicting individual autonomy. The option about a restrictive view of political engagement failing to recognize political dimensions of individual autonomy accurately captures this layered main idea. The claim that Wright eventually revised his assessment fabricates information not present in the passage. The assertion that Hurston deliberately avoided political themes contradicts Chandrasekaran''s argument, which holds that the novel was political — just in a way critics failed to recognize. The suggestion that the novel was initially praised and later fell out of favor reverses the actual reception described in the passage, where contemporary reviewers criticized it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DWCJ6M', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Based on the texts, how would the author of Text 1 most likely characterize the evidence presented in Text 2?', E'Text 1: Paleoclimatologist Yuki Tanabe has proposed that the abrupt cooling event recorded in Greenland ice cores approximately 8,200 years ago was triggered by the catastrophic drainage of glacial Lake Agassiz into the North Atlantic, which disrupted thermohaline circulation. Tanabe emphasizes that the timing of the lake''s collapse, as established by varve chronologies in Manitoba, aligns with the onset of cooling to within 50 years, a correspondence she considers too precise to be coincidental.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EICFES', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Ecologists studying salt marshes along the Georgia coast hypothesize that the invasive green crab (Carcinus maenas) is reducing populations of native ribbed mussels by consuming juvenile mussels before they can establish themselves in marsh sediment. The researchers note that ribbed mussel densities have declined by approximately 40 percent in marshes where green crabs were first observed seven years ago, while mussel populations in nearby marshes without green crabs have remained stable.', $lyceon_json$[{"key":"A","text":"Green crabs in laboratory settings consumed juvenile ribbed mussels at significantly higher rates than they consumed adult mussels of the same species."},{"key":"B","text":"Ribbed mussel populations in marshes without green crabs have increased over the same seven-year period."},{"key":"C","text":"Green crabs were introduced to the Georgia coast through ballast water discharge from commercial shipping vessels."},{"key":"D","text":"Adult ribbed mussels in green-crab-inhabited marshes show signs of increased stress compared to those in unaffected marshes."}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis specifically proposes that green crabs reduce mussel populations by consuming juvenile mussels before they establish themselves. A laboratory finding that green crabs consume juvenile mussels at significantly higher rates than adults directly supports the mechanism described in the hypothesis. The finding that mussel populations in unaffected marshes increased does not address the causal mechanism of green crab predation on juveniles. Information about how green crabs arrived via ballast water explains their introduction but says nothing about their impact on mussels. Evidence that adult mussels show increased stress relates to adult health rather than the hypothesized predation on juveniles.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FAIZTN', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In 2019, archaeologists excavating a site near Plovdiv, Bulgaria, uncovered a trove of Thracian gold artifacts dating to the fourth century BCE. The artifacts, which included ornate drinking vessels and ceremonial ______ the Thracians possessed metalworking techniques rivaling those of their Greek contemporaries.', $lyceon_json$[{"key":"A","text":"breastplates, suggest that"},{"key":"B","text":"breastplates. Suggest that"},{"key":"C","text":"breastplates suggest, that"},{"key":"D","text":"breastplates; suggest that"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence contains a nonrestrictive relative clause (''which included ornate drinking vessels and ceremonial breastplates'') that must be closed with a comma before the main clause resumes with its verb ''suggest.'' The comma after ''breastplates'' closes the parenthetical clause, and ''that'' introduces the noun clause serving as the object of ''suggest.'' The option placing a period after ''breastplates'' fragments the sentence by severing the verb from its subject. The option placing a comma between ''suggest'' and ''that'' incorrectly separates the verb from its noun-clause complement. The option using a semicolon after ''breastplates'' incorrectly treats ''suggest that'' as beginning a new independent clause when it is actually the predicate of the main sentence whose subject is ''The artifacts.''', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FTHL2A', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'In 1847, physician Ignaz Semmelweis observed that the mortality rate in a Vienna maternity ward staffed by medical students was nearly five times that of a ward staffed by midwives. He hypothesized that medical students, who often came directly from performing autopsies, carried "cadaverous particles" on their hands. When Semmelweis instituted mandatory handwashing with a chlorinated lime solution, the mortality rate in the students'' ward dropped from 18.3 percent to 1.3 percent within three months. Despite this dramatic result, the broader medical establishment dismissed his findings, and widespread adoption of antiseptic handwashing did not occur until decades later.', $lyceon_json$[{"key":"A","text":"It presents an observation, describes a hypothesis and its successful test, and then notes an ironic historical outcome."},{"key":"B","text":"It compares two competing theories about disease transmission and evaluates which one better explains the available evidence."},{"key":"C","text":"It traces the gradual acceptance of a medical innovation from its initial proposal to its widespread adoption."},{"key":"D","text":"It describes an experimental failure and explains the methodological flaws that led to its rejection by the scientific community."}]$lyceon_json$::jsonb, 'A', NULL, E'The text follows a clear sequence: Semmelweis observes a mortality disparity, forms a hypothesis about cadaverous particles, tests it with handwashing (which succeeds dramatically), and then the passage ends by noting that the medical establishment rejected his findings despite their success. This matches the description of an observation leading to a hypothesis and successful test followed by an ironic outcome. The option about comparing two competing theories is incorrect because only one hypothesis is presented. The option about tracing gradual acceptance is incorrect because the passage explicitly states that widespread adoption did not occur until decades later, meaning the text does not describe acceptance. The option about experimental failure is incorrect because the experiment succeeded in reducing mortality.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KHVBTX', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing a policy brief about municipal composting programs. The student wants to acknowledge a limitation of curbside composting while arguing that its environmental benefits justify expansion of the program. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'- San Mateo County''s curbside composting program, launched in 2019, diverts an estimated 31,000 tons of organic waste from landfills annually.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KLVFDL', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the overall structure of the text?', E'Monarch butterflies undertake one of the longest insect migrations on Earth, traveling up to 4,800 kilometers from southern Canada to central Mexico each autumn. Scientists have long puzzled over how an insect with a brain smaller than a pinhead navigates with such precision. Recent experiments by neurobiologist Eli Warrant revealed that monarchs use a time-compensated sun compass housed in their antennae, adjusting their flight direction throughout the day as the sun moves across the sky.', $lyceon_json$[{"key":"A","text":"It introduces a scientific question that subsequent research findings address."},{"key":"B","text":"It provides evidence that challenges a widely held assumption about insect behavior."},{"key":"C","text":"It describes the methodology used in a particular experiment."},{"key":"D","text":"It presents a conclusion drawn from the research discussed later in the text."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence presents the puzzle of how a tiny-brained insect navigates so precisely, which the final sentence then answers with the sun compass discovery. This makes it a question-setting sentence that frames subsequent research findings. The option about challenging a widely held assumption is incorrect because the sentence poses a question rather than contradicting any established view. The option about describing methodology is incorrect because the sentence does not discuss experimental procedures. The option about presenting a conclusion is incorrect because the sentence raises a question rather than stating a finding.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LCXYT4', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'In her 2019 monograph on Mesoamerican ceramics, archaeologist Renata Solís argued that the intricate geometric motifs adorning Zapotec funerary urns were not merely decorative but served a ______ function, encoding information about the deceased''s lineage and social rank in a visual language legible to contemporaries.', $lyceon_json$[{"key":"A","text":"semantic"},{"key":"B","text":"provisional"},{"key":"C","text":"peripheral"},{"key":"D","text":"therapeutic"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that the motifs encoded information in a visual language, indicating they carried meaning. The word relating to meaning and signification fits this context. "Provisional" means temporary or conditional, which does not relate to encoding information about lineage. "Peripheral" means marginal or secondary, which contradicts the passage''s argument that the function was significant rather than merely decorative. "Therapeutic" means relating to healing, which has no connection to the communicative role described in the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2N14EDO', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief introduction to a presentation about urban beekeeping. The student wants to emphasize the growing popularity of beekeeping in cities. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'- Urban beekeeping involves maintaining honeybee colonies on rooftops, balconies, or community garden plots within city limits.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2N9IFCF', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'When the Voyager 1 spacecraft crossed into interstellar space in August 2012, it ______ more than 35 years since the probe''s launch from Cape Canaveral on September 5, 1977.', $lyceon_json$[{"key":"A","text":"had been"},{"key":"B","text":"has been"},{"key":"C","text":"was being"},{"key":"D","text":"would be"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence describes a duration of time that had elapsed before a past event (crossing into interstellar space in 2012). The past perfect ''had been'' correctly indicates that the 35-year span was completed prior to the past-tense main event. The present perfect ''has been'' incorrectly shifts to a tense anchored to the present moment, conflicting with the past-tense context of the passage. The past progressive ''was being'' illogically suggests an ongoing process of ''being'' a duration rather than a completed elapsed period. The conditional ''would be'' implies a hypothetical or future-in-the-past scenario, but the sentence states a factual elapsed duration.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2NAVZO3', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'In 2019, marine biologist Ayana Morales published findings on the feeding behavior of giant Pacific octopuses in Puget Sound. Morales documented 137 hunting episodes across 19 individuals over eleven months. She observed that octopuses overwhelmingly preferred Dungeness crabs when available, but during months when crab populations declined — particularly between late February and mid-April — the octopuses shifted to consuming smaller prey such as snails and hermit crabs. Morales noted that this dietary flexibility did not appear to compromise the octopuses'' growth rates, suggesting that their nutritional needs were met even with substitute prey. She concluded that the species'' adaptability in prey selection may buffer it against short-term fluctuations in any single prey population.', $lyceon_json$[{"key":"A","text":"Giant Pacific octopuses demonstrate dietary flexibility that may protect them from the effects of temporary declines in preferred prey populations."},{"key":"B","text":"Giant Pacific octopuses in Puget Sound are threatened by declining Dungeness crab populations and must find alternative food sources to survive."},{"key":"C","text":"Ayana Morales's research proved that giant Pacific octopuses grow at the same rate regardless of what type of prey they consume."},{"key":"D","text":"The hunting behavior of giant Pacific octopuses is primarily driven by seasonal water temperature changes in Puget Sound."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on how giant Pacific octopuses shift their diet when preferred prey declines and how this flexibility may buffer the species against fluctuations in any single prey population. The option about dietary flexibility protecting against temporary prey declines captures this main idea. The claim that octopuses are threatened by declining crab populations overstates the passage, which describes temporary seasonal fluctuation, not an existential threat. The assertion that Morales proved identical growth rates regardless of prey type distorts her finding — she noted growth rates did not appear compromised, which is weaker than proving equivalence across all prey types. The suggestion that hunting behavior is primarily driven by water temperature introduces a cause not mentioned in the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2O99QW8', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'During the 1930s, the Australian government imported cane toads from Hawaii to control beetle populations damaging sugarcane crops. The toads, however, proved ineffective against the ______ they thrived in the wild, spreading rapidly across northeastern Queensland and displacing native amphibian species.', $lyceon_json$[{"key":"A","text":"beetles. Instead,"},{"key":"B","text":"beetles, instead,"},{"key":"C","text":"beetles instead"},{"key":"D","text":"beetles; instead"}]$lyceon_json$::jsonb, 'A', NULL, E'Two independent clauses need a clear boundary here. A period followed by the conjunctive adverb ''Instead'' with a comma properly separates the two complete thoughts and signals the contrasting relationship. The option using commas around ''instead'' creates a comma splice between two independent clauses. The option with no punctuation before or after ''instead'' produces a fused sentence. The option using a semicolon omits the required comma after the conjunctive adverb ''instead,'' violating standard punctuation conventions for conjunctive adverbs.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QETEX8', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Although the poet Kwame Adjei''s early verse was celebrated for its lush imagery, critics noted that his later collections adopted a deliberately ______ style, stripping away ornamental language until each poem consisted of spare, unadorned declarations that forced readers to confront the raw substance of his observations without aesthetic cushioning.', $lyceon_json$[{"key":"A","text":"austere"},{"key":"B","text":"erratic"},{"key":"C","text":"nostalgic"},{"key":"D","text":"didactic"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a deliberate shift toward stripping away ornamental language, leaving spare and unadorned declarations. The word meaning severe simplicity and lack of decoration precisely captures this stylistic choice. "Erratic" means unpredictable or inconsistent, but the passage describes a deliberate and consistent stylistic direction, not randomness. "Nostalgic" means wistful longing for the past, which the passage never suggests; the poet moved away from his earlier style rather than yearning for it. "Didactic" means intended to teach a moral lesson, but the passage focuses on the stripped-down aesthetic quality of the poetry, not on any instructional purpose.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SSPEEB', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing a research summary about the Indus script. The student wants to present a contrast between two scholarly positions on whether the Indus script encodes a spoken language. Which choice most effectively uses the relevant information from the notes to accomplish this goal?', E'- The Indus script, used by the Harappan civilization from approximately 2600 to 1900 BCE, consists of roughly 417 distinct signs.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SZYQTG', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Svalbard Global Seed Vault, located on a Norwegian archipelago approximately 1,300 kilometers from the North Pole, ______ backup copies of seeds from gene banks worldwide to safeguard crop diversity against natural disasters and conflicts.', $lyceon_json$[{"key":"A","text":"stores"},{"key":"B","text":"store"},{"key":"C","text":"storing"},{"key":"D","text":"have stored"}]$lyceon_json$::jsonb, 'A', NULL, E'The subject of the sentence is the singular noun ''The Svalbard Global Seed Vault,'' which requires a singular verb form. The third-person singular present tense ''stores'' agrees with this subject. The base form ''store'' is plural and does not agree with the singular subject. The present participle ''storing'' creates a sentence fragment because it cannot serve as a finite verb. The form ''have stored'' uses a plural auxiliary that does not agree with the singular subject.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2T3FX3C', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding, if true, would most directly undermine the researchers'' conclusion?', E'A team of cognitive scientists at the University of Helsinki conducted a study in which 214 adults completed a series of decision-making tasks after either a full night of sleep or a night of restricted sleep (four hours). Participants who slept only four hours made riskier choices on a simulated gambling task and reported higher confidence in those choices compared to well-rested participants. The researchers concluded that sleep deprivation impairs the brain''s ability to accurately assess risk, creating a dangerous combination of increased risk-taking and inflated self-assurance.', $lyceon_json$[{"key":"A","text":"Participants who slept only four hours performed worse than well-rested participants on a separate memory recall task administered during the same session."},{"key":"B","text":"When the gambling task was repeated with real monetary stakes rather than simulated ones, sleep-deprived participants made choices that were statistically indistinguishable from those of well-rested participants."},{"key":"C","text":"A follow-up survey revealed that sleep-deprived participants were more likely than well-rested participants to report feeling fatigued during the experiment."},{"key":"D","text":"Neuroimaging data collected during the study showed reduced activity in the prefrontal cortex of sleep-deprived participants during the gambling task."}]$lyceon_json$::jsonb, 'B', NULL, E'The researchers concluded that sleep deprivation impairs risk assessment, leading to riskier choices. If sleep-deprived participants made choices indistinguishable from well-rested participants when real money was at stake, this would suggest the original finding was an artifact of the simulated context rather than a genuine impairment in risk assessment — directly undermining the conclusion. Worse performance on a memory recall task shows a different cognitive deficit but does not address whether sleep deprivation specifically impairs risk assessment. Sleep-deprived participants reporting fatigue is expected and consistent with the researchers'' conclusion rather than undermining it. Reduced prefrontal cortex activity in sleep-deprived participants would actually support, not undermine, the conclusion that sleep deprivation impairs cognitive processes related to risk assessment.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2T458E2', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'What can most reasonably be inferred from the text?', E'Between 2016 and 2021, the city of Medellín, Colombia, planted corridors of trees and vegetation along 36 major roads and waterways as part of its "Green Corridors" initiative. City officials reported that average surface temperatures in these corridors dropped by up to 3 degrees Celsius compared to adjacent streets without vegetation. The initiative cost approximately 16.3 million dollars over five years.', $lyceon_json$[{"key":"A","text":"Urban areas without tree cover in Medellín tend to have higher surface temperatures than areas with substantial vegetation."},{"key":"B","text":"Medellín's Green Corridors initiative was the most cost-effective urban cooling program implemented in South America."},{"key":"C","text":"The temperature reduction achieved by the Green Corridors would be even greater in cities with hotter climates than Medellín's."},{"key":"D","text":"Medellín's city officials prioritized the Green Corridors initiative over all other infrastructure projects during the 2016–2021 period."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that corridors with planted vegetation experienced surface temperatures up to 3 degrees Celsius lower than adjacent streets without vegetation. From this, it can be reasonably inferred that urban areas lacking tree cover in Medellín tend to have higher surface temperatures than vegetated areas. The claim about being the most cost-effective program in South America introduces a comparative superlative with no basis in the passage. The prediction that hotter cities would see even greater temperature reductions speculates beyond the data provided. The assertion that city officials prioritized this initiative over all other infrastructure projects cannot be supported by the passage, which mentions only the cost and results of the program.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2U2ER1W', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'The parasitic Ophiocordyceps fungus manipulates the behavior of carpenter ants, compelling infected individuals to climb vegetation and clamp their mandibles onto a leaf vein before dying — a position that optimizes spore dispersal. Recent genomic analyses, however, have revealed that the fungus does not directly invade the ant''s brain tissue. _______ the fungus secretes a cocktail of neuromodulatory compounds that hijack the ant''s muscle and peripheral nervous system, effectively controlling the host''s movements without breaching the central nervous system.', $lyceon_json$[{"key":"A","text":"Instead,"},{"key":"B","text":"Moreover,"},{"key":"C","text":"For instance,"},{"key":"D","text":"Accordingly,"}]$lyceon_json$::jsonb, 'A', NULL, E'The preceding sentence establishes that the fungus does not invade the brain, and the blank sentence describes an alternative mechanism — secreting compounds that control the peripheral system. This substitution relationship requires a transition indicating replacement of one explanation with another. The addition transition is wrong because the third sentence does not merely add information to the idea of brain invasion; it replaces that mechanism with a different one. The exemplification transition is wrong because the third sentence is not providing an example of the fungus avoiding the brain; it is presenting the actual alternative strategy. The consequence transition is wrong because the peripheral-control mechanism is not a logical result of the fungus failing to invade the brain — it is an alternative method the fungus employs.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2U7S9C0', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Marine biologists studying the migration patterns of loggerhead sea turtles have found that the animals demonstrate remarkable ______ in returning to their natal beaches to nest, often traveling thousands of miles across open ocean to reach the exact stretch of sand where they hatched decades earlier.', $lyceon_json$[{"key":"A","text":"fidelity"},{"key":"B","text":"tolerance"},{"key":"C","text":"ambiguity"},{"key":"D","text":"brevity"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes sea turtles consistently returning to the exact same beaches where they hatched, which indicates steadfast devotion to a particular location. The word meaning loyal commitment to a place or habit fits this context precisely. "Tolerance" refers to the ability to endure difficult conditions, which does not address the turtles'' consistent return behavior. "Ambiguity" means uncertainty or vagueness, which contradicts the passage''s emphasis on precision. "Brevity" means shortness in duration, which is irrelevant to the turtles'' navigational consistency.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2V0SBTO', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'In a 2024 study examining sediment cores from Lake Ohrid on the border of Albania and North Macedonia, geochemist Elira Dushku and her colleagues analyzed pollen records spanning 1.4 million years. Dushku''s research, alongside findings from parallel investigations conducted at three other ancient ______ that Mediterranean vegetation zones shifted dramatically during glacial periods, sometimes retreating over 400 kilometers southward within a few thousand years.', $lyceon_json$[{"key":"A","text":"lakes, demonstrates"},{"key":"B","text":"lakes demonstrates"},{"key":"C","text":"lakes, demonstrate"},{"key":"D","text":"lakes; demonstrate"}]$lyceon_json$::jsonb, 'A', NULL, E'The subject of the verb is the singular noun ''research,'' modified by the parenthetical phrase ''alongside findings from parallel investigations conducted at three other ancient lakes.'' This phrase must be set off by a comma before the verb. The singular verb ''demonstrates'' correctly agrees with the singular subject ''research.'' The option omitting the comma after ''lakes'' fails to close the parenthetical modifier, creating a misparse in which ''lakes'' appears to be the subject. The option using ''demonstrate'' pairs a plural verb with the singular subject ''research,'' an agreement error likely caused by attraction to the nearby plural ''lakes'' or ''investigations.'' The option using a semicolon before ''demonstrate'' incorrectly treats the verb and its complement as a new independent clause, severing it from its subject.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VIEPH7', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Based on the text, what can most reasonably be inferred about Xu''s interpretation of the archaeological evidence?', E'Archaeologist Lin Xu challenges the prevailing view that the abandonment of the ancient city of Shimao in northern China around 1800 BCE was caused by prolonged drought. Xu acknowledges that paleoclimate data confirm a significant drying period in the region beginning around 1900 BCE, but she points out that Shimao''s extensive grain storage facilities — capable of holding an estimated 50 metric tons of millet — were found nearly empty, with no evidence of the insect remains or rodent damage typically associated with long-term grain storage. Xu argues that this pattern is more consistent with a rapid, organized departure than with a gradual decline driven by failing harvests. She further notes that several elite residences show signs of deliberate, controlled burning rather than the haphazard destruction associated with military conquest.', $lyceon_json$[{"key":"A","text":"Xu believes that while drought occurred in the region, the specific evidence at Shimao suggests the population left deliberately and in an organized manner rather than being slowly driven out by crop failure."},{"key":"B","text":"Xu concludes that the drought around 1900 BCE did not actually affect the Shimao region and that paleoclimate data have been misinterpreted by other researchers."},{"key":"C","text":"Xu argues that Shimao was abandoned because of military conquest, as evidenced by the burning of elite residences throughout the city."},{"key":"D","text":"Xu proposes that the empty grain storage facilities prove Shimao's residents had already exhausted their food supply before abandoning the city."}]$lyceon_json$::jsonb, 'A', NULL, E'Xu acknowledges the drought occurred but argues the archaeological evidence — empty granaries without signs of long-term storage and deliberately burned residences — points to a rapid, organized departure rather than gradual decline from crop failure. The option about Xu believing drought occurred but the evidence suggesting deliberate, organized departure captures this nuanced interpretation. The claim that Xu concludes drought did not affect the region misrepresents her position; she acknowledges the drying period but disputes its role as the cause of abandonment. The assertion that Xu argues for military conquest contradicts the passage, which states Xu distinguishes the controlled burning from haphazard destruction associated with military conquest. The suggestion that empty granaries prove food exhaustion reverses Xu''s argument — she contends the lack of insect remains and rodent damage indicates the grain was removed intentionally, not consumed over time.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WM8DFM', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'During the seventeenth century, glassmakers in Murano, Italy, closely guarded their techniques for producing crystal-clear glass, and the Venetian government imposed severe penalties on artisans who attempted to leave the island. _______ a handful of craftsmen did manage to flee to neighboring countries, where they established rival workshops that eventually eroded Venice''s monopoly on luxury glassware.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"Consequently,"},{"key":"C","text":"Even so,"},{"key":"D","text":"Similarly,"}]$lyceon_json$::jsonb, 'C', NULL, E'The first sentence describes strict measures to prevent artisans from leaving, while the second sentence reveals that some artisans escaped despite those measures. This is a concession relationship: the outcome occurred contrary to what the protective measures were intended to achieve. The addition transition is wrong because the second sentence does not simply add a parallel fact; it introduces an outcome that runs counter to the restrictions. The cause-and-effect transition is wrong because fleeing was not a result of the penalties but occurred in spite of them. The comparison transition is wrong because no similarity between two comparable situations is being drawn.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2X6ZBWQ', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Economists have long assumed that individuals in developing nations underinvest in preventive health measures primarily because of cost barriers. A 2023 field experiment in rural Senegal, however, challenged this view: when researchers offered free malaria bed nets alongside modest cash incentives, uptake rose only marginally compared to offering the nets alone. _______ when researchers paired the free nets with community-led educational workshops explaining the long-term household savings from preventing malaria, adoption rates nearly tripled — suggesting that informational barriers, not financial ones, were the binding constraint.', $lyceon_json$[{"key":"A","text":"By contrast,"},{"key":"B","text":"In addition,"},{"key":"C","text":"That is,"},{"key":"D","text":"As a result,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage sets up two experimental conditions with starkly different results: cash incentives produced only marginal improvement, whereas educational workshops nearly tripled adoption. The blank introduces the second condition, which is being compared against and contrasted with the first. A contrast transition correctly signals this juxtaposition. The addition transition is wrong because the third sentence is not simply adding another supporting detail; it is presenting a competing condition with a dramatically different outcome. The restatement transition is wrong because the third sentence introduces new experimental results rather than rephrasing what has already been stated. The cause-and-effect transition is wrong because the workshop condition is not a consequence of the cash-incentive finding but an alternative intervention tested alongside it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XC5KRD', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Researchers at the University of Zurich recently discovered that certain alpine mosses can survive being frozen at temperatures as low as negative forty-three degrees Celsius for up to seven months. _______ these mosses resume photosynthesis within hours of thawing, suggesting that their cellular repair mechanisms activate almost immediately upon exposure to warmth.', $lyceon_json$[{"key":"A","text":"Remarkably,"},{"key":"B","text":"In contrast,"},{"key":"C","text":"Nevertheless,"},{"key":"D","text":"Specifically,"}]$lyceon_json$::jsonb, 'A', NULL, E'The second sentence adds a surprising and noteworthy detail about the mosses resuming photosynthesis within hours, which builds on the already impressive fact of surviving extreme cold. The transition indicating surprise or emphasis is the correct choice. The contrast transition is wrong because the second sentence does not oppose the first; it extends and amplifies it. The concession transition is wrong because there is no obstacle or counterpoint being overcome. The specification transition is wrong because the second sentence introduces a new, notable fact rather than narrowing down information already stated.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-19"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-19","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
